using System.Data;
using CoffeManager.Infrastructure.Database;
namespace CoffeManager.Models.User.Repositories;
internal sealed partial class AccountRepository
{
    #region Task Account Operations
        /// <summary>Creates an unlinked staff account under the owner without granting operational permissions.</summary>
        /// <param name="ownerId">The owner identifier resolved from the authenticated session.</param>
        /// <param name="data">The interaction fields supplied for this request.</param>
        /// <param name="passwordHash">The password hash generated by the server.</param>
        /// <param name="cancellationToken">Cancels the asynchronous operation.</param>
        internal async Task<Guid> CreateStaffAsync(Guid ownerId,StaffAccountRegistrationData data,string passwordHash,CancellationToken cancellationToken)
        {
            await using var connection=await connections.OpenAsync(cancellationToken);using var command=connection.CreateCommand();var id=Guid.NewGuid();
            command.CommandText="INSERT dbo.Accounts(UserId,OwnerUserId,FirstName,PaternalLastName,MaternalLastName,Email,NormalizedEmail,PasswordHash,DisplayName,IsOwner) SELECT @id,UserId,@first,@last,@second,@email,@normalized,@hash,@display,0 FROM dbo.Accounts WHERE UserId=@owner AND IsOwner=1 AND IsEnabled=1";
            command.Id("@id",id);command.Id("@owner",ownerId);command.Text("@first",data.FirstName.Trim(),80);command.Text("@last",data.PaternalLastName.Trim(),80);command.Text("@second",data.MaternalLastName,80);command.Text("@email",data.Email.Trim(),254);command.Text("@normalized",data.Email.Trim().ToUpperInvariant(),254);command.Text("@hash",passwordHash,512);command.Text("@display",data.FirstName.Trim(),100);
            if(await command.ExecuteNonQueryAsync(cancellationToken)!=1)throw new UnauthorizedAccessException();return id;
        }
        /// <summary>Returns unlinked non-owner accounts within the caller's business scope.</summary>
        /// <param name="ownerId">The owner identifier resolved from the authenticated session.</param>
        /// <param name="cancellationToken">Cancels the asynchronous operation.</param>
        internal async Task<IReadOnlyList<AvailableAccountData>> GetAvailableAccountsAsync(Guid ownerId,CancellationToken cancellationToken)
        {
            await using var connection=await connections.OpenAsync(cancellationToken);using var command=connection.CreateCommand();
            command.CommandText="SELECT a.UserId,a.DisplayName,a.Email FROM dbo.Accounts a WHERE a.OwnerUserId=@owner AND a.IsOwner=0 AND a.IsEnabled=1 AND NOT EXISTS(SELECT 1 FROM dbo.Employees e WHERE e.UserAccountId=a.UserId) ORDER BY a.DisplayName";command.Id("@owner",ownerId);
            await using var reader=await command.ExecuteReaderAsync(cancellationToken);var result=new List<AvailableAccountData>();
            while(await reader.ReadAsync(cancellationToken))result.Add(new AvailableAccountData{UserAccountId=reader.GetGuid(0),DisplayName=reader.GetString(1),Email=reader.GetString(2)});return result;
        }
        /// <summary>Re-evaluates current access on every authenticated request; account credentials remain intact after role changes.</summary>
        /// <param name="userId">The authenticated user identifier.</param>
        /// <param name="cancellationToken">Cancels the asynchronous operation.</param>
        internal async Task<(Guid OwnerId,bool IsOwner,int Version,bool CanAdmin,bool CanCheckout)?> GetAccessAsync(Guid userId,CancellationToken cancellationToken)
        {
            await using var connection=await connections.OpenAsync(cancellationToken);using var command=connection.CreateCommand();
            command.CommandText="SELECT COALESCE(a.OwnerUserId,a.UserId),a.IsOwner,a.AuthVersion,CAST(CASE WHEN a.IsOwner=1 OR (e.BranchId IS NOT NULL AND r.CanAccessAdministration=1 AND (e.EmploymentStatusId IS NULL OR st.Code=N'Active')) THEN 1 ELSE 0 END AS bit),CAST(CASE WHEN a.IsOwner=1 OR (e.BranchId IS NOT NULL AND r.CanAccessCheckout=1 AND (e.EmploymentStatusId IS NULL OR st.Code=N'Active')) THEN 1 ELSE 0 END AS bit) FROM dbo.Accounts a LEFT JOIN dbo.Employees e ON e.UserAccountId=a.UserId LEFT JOIN dbo.Roles r ON r.RoleId=e.RoleId LEFT JOIN dbo.EmploymentStatuses st ON st.Id=e.EmploymentStatusId WHERE a.UserId=@id AND a.IsEnabled=1";command.Id("@id",userId);
            await using var reader=await command.ExecuteReaderAsync(cancellationToken);return await reader.ReadAsync(cancellationToken)?(reader.GetGuid(0),reader.GetBoolean(1),reader.GetInt32(2),reader.GetBoolean(3),reader.GetBoolean(4)):null;
        }
    #endregion Task Account Operations
    #region Task Role Operations
        /// <summary>Reads the role catalog persisted during controlled setup or owner configuration.</summary>
        /// <param name="cancellationToken">Cancels the asynchronous operation.</param>
        internal async Task<IReadOnlyList<RoleData>> GetRolesAsync(CancellationToken cancellationToken)
        {
            await using var connection=await connections.OpenAsync(cancellationToken);using var command=connection.CreateCommand();command.CommandText="SELECT RoleId,Name,CanAccessAdministration,CanAccessCheckout FROM dbo.Roles ORDER BY Name";
            await using var reader=await command.ExecuteReaderAsync(cancellationToken);var result=new List<RoleData>();while(await reader.ReadAsync(cancellationToken))result.Add(new RoleData{RoleId=reader.GetGuid(0),Name=reader.GetString(1),CanAccessAdministration=reader.GetBoolean(2),CanAccessCheckout=reader.GetBoolean(3)});return result;
        }
        /// <summary>Creates a role with explicit capabilities; only owner-authorized API calls reach this method.</summary>
        /// <param name="data">The interaction fields supplied for this request.</param>
        /// <param name="cancellationToken">Cancels the asynchronous operation.</param>
        internal async Task<Guid> AddRoleAsync(RoleCreationData data,CancellationToken cancellationToken)
        {
            await using var connection=await connections.OpenAsync(cancellationToken);using var command=connection.CreateCommand();var id=Guid.NewGuid();
            command.CommandText="INSERT dbo.Roles(RoleId,Code,Name,CanAccessAdministration,CanAccessCheckout) VALUES(@id,@code,@name,@admin,@checkout)";command.Id("@id",id);command.Text("@code",id.ToString("N"),50);command.Text("@name",data.Name.Trim(),100);command.Parameters.Add("@admin",SqlDbType.Bit).Value=data.CanAccessAdministration;command.Parameters.Add("@checkout",SqlDbType.Bit).Value=data.CanAccessCheckout;await command.ExecuteNonQueryAsync(cancellationToken);return id;
        }
    #endregion Task Role Operations
}
